/**
 * Returns the caller's currently-active multi-batch draft checkout
queue, if any. Auto-prunes chunks whose jobs have all already left
`draft` status (e.g. paid via the single-job button or via the
webhook for a previous batch) before returning, so the response
always reflects what's still actually payable. Returns 404 when
there is no active queue.

 * @summary Active split-checkout queue for the caller (attorney only)
 */
export const GetMyDraftCheckoutQueueResponse = zod.object({
  id: zod.number(),
  chunks: zod
    .array(zod.array(zod.number()))
    .describe(
      "Ordered batches of draft job ids. The next batch to pay is\n`chunks[paidCount]`. Chunks already fully paid have been\npruned by the server before this response is returned.\n",
    ),
  paidCount: zod
    .number()
    .describe(
      "Number of leading chunks that have already been paid for.\nAlways `< chunks.length` for an active queue.\n",
    ),
  totalCents: zod
    .number()
    .describe("Sum of `grossCents` across all chunks at queue creation time."),
  expiresAt: zod.coerce
    .date()
    .describe("Hard TTL — the queue stops being shown after this time."),
  createdAt: zod.coerce.date(),
  updatedAt: zod.coerce.date(),
});

/**
 * Persists the planned chunks for a multi-batch checkout so the
attorney can resume after closing the tab or signing in on a
different device. Replaces any existing queue for the caller.
All referenced jobs must currently be in `draft` status and
belong to the caller.

 * @summary Save (or replace) the caller's split-checkout queue (attorney only)
 */
export const upsertMyDraftCheckoutQueueBodyChunksItemMax = 50;

export const upsertMyDraftCheckoutQueueBodyChunksMin = 2;

export const UpsertMyDraftCheckoutQueueBody = zod.object({
  chunks: zod
    .array(
      zod
        .array(zod.number())
        .min(1)
        .max(upsertMyDraftCheckoutQueueBodyChunksItemMax),
    )
    .min(upsertMyDraftCheckoutQueueBodyChunksMin)
    .describe(
      "Ordered batches of draft job ids. Must contain at least two\nchunks — a single-chunk selection doesn't need a queue\nbecause there is nothing to resume after the one Checkout\nsession completes.\n",
    ),
  totalCents: zod
    .number()
    .describe("Display-only total in cents across all chunks."),
});

