/**
 * Creates a Stripe Checkout session with one line item per draft job
owned by the calling attorney. Each line item uses the snapshot
`grossCents` stored on the job row at create time. On successful
completion the webhook flips every covered job from `draft` to
`pending`.

 * @summary Start Stripe Checkout to pay for one or more draft jobs (attorney only)
 */
export const createDraftJobsCheckoutBodyJobIdsMax = 50;

export const CreateDraftJobsCheckoutBody = zod.object({
  jobIds: zod
    .array(zod.number())
    .min(1)
    .max(createDraftJobsCheckoutBodyJobIdsMax)
    .describe(
      "Ids of draft jobs to pay for in a single Checkout session. All\nids must belong to the calling attorney and currently be in\n`draft` status.\n",
    ),
  queueId: zod
    .number()
    .nullish()
    .describe(
      "Optional id of a `DraftCheckoutQueue` row this batch belongs\nto. When supplied, the webhook will atomically increment the\nqueue's `paidCount` once Stripe confirms the session, so the\nresume banner advances on its own and the next batch is ready\nwithout any client-side bookkeeping.\n",
    ),
});

export const CreateDraftJobsCheckoutResponse = zod.object({
  url: zod
    .string()
    .describe("Hosted Stripe Checkout URL to redirect the attorney to."),
  sessionId: zod.string(),
  totalCents: zod
    .number()
    .describe("Sum of `grossCents` across all included jobs (display only)."),
});

